from typing import List
from textkit.normalize_whitespace import normalize_whitespace
import re

def split_sentences(text: str) -> List[str]:
    if not text: return []
    norm = normalize_whitespace(text)
    if not norm: return []
    words = norm.split()
    if not words: return []
    abbr = {"Mr.", "Mrs.", "Ms.", "Dr.", "Prof.", "St.", "vs.", "e.g.", "i.e."}
    term_re = r'[.!\?]+["'\)\]]*$'
    res, cur = [], []
    for i, w in enumerate(words):
        cur.append(w)
        if w in abbr: continue
        if len(w) == 2 and w[0].isupper() and w[1] == '.': continue
        if re.search(term_re, w):
            if i == len(words) - 1:
                res.append(" ".join(cur))
                cur = []
            else:
                nxt = words[i+1]
                if nxt[0].isupper() or nxt[0].isdigit() or nxt[0] in "'(\[":
                    res.append(" ".join(cur))
                    cur = []
    if cur: res.append(" ".join(cur))
    return res"
    }
  },
